                function checkSkinHold() {
                    const now = Date.now();
                    const currentSkin = player.latestSkin;

                    // If skin changed, reset timer
                    if (timeHoldingSkin.skin !== currentSkin) {
                        timeHoldingSkin.skin = currentSkin;
                        timeHoldingSkin.since = now;
                        timeHoldingSkin.announced = false;
                        return;
                    }

                    // Only care about skin 40
                    if (currentSkin !== 40) return;

                    const heldFor = (now - timeHoldingSkin.since) / 1000;

                    if (heldFor >= 300 && !timeHoldingSkin.announced) {
                        sendChat("skin 40 for 300s"); // <= must be â‰¤ 30 chars
                        timeHoldingSkin.announced = true;
                    }
                }

