                function sendAutoGather() {
                    if (secPacket >= 90) {
                        if (!_things.autoGatherRetry) {
                            _things.autoGatherRetry = setTimeout(function tryAutoGather() {
                                if (secPacket < 90) {
                                    _things.autoGatherRetry = null;
                                    packet("K", 1, 1);
                                    return;
                                }
                                _things.autoGatherRetry = setTimeout(tryAutoGather, 120);
                            }, 120);
                        }
                        return false;
                    }
                    packet("K", 1, 1);
                    return true;
                }
                function sendReloadCheckedHit(config) {
                    const weapon = config.weapon;
                    const reload = player.reloads && Number(player.reloads[weapon]) || 0;
                    const checkTicks = Math.max(1, Number(config.checkTicks) || 1);

                    if (!(weapon || weapon === 0) || my.waitHit || reload > (pingTime || 0)) {
                        return false;
                    }

                    if (config.selectWeapon !== false && (player.weaponIndex !== weapon || player.buildIndex > -1)) {
                        selectWeapon(weapon);
                    }

                    const waitKey = config.waitKey;
                    const stateKey = config.stateKey || "_reloadHitCheck";
                    const state = {
                        tag: config.tag || "ReloadHit",
                        weapon,
                        waitKey,
                        sentTick: game.tick,
                        beforeReload: reload,
                        retried: false,
                        fired: false
                    };
                    const sendStart = config.sendStart || sendAutoGather;
                    const sendStop = config.sendStop || sendAutoGather;
                    const clearWait = () => {
                        my.waitHit = 0;
                        if (waitKey) {
                            _things[waitKey] = 0;
                            _things[waitKey + "_time"] = 0;
                        }
                        if (config.afterClear) config.afterClear(state);
                    };

                    my.waitHit = 1;
                    if (waitKey) {
                        _things[waitKey] = 1;
                        _things[waitKey + "_time"] = Date.now();
                    }
                    _things[stateKey] = state;
                    if (config.beforeStart) config.beforeStart(state);
                    sendStart(state);

                    game.tickBase(() => {
                        if (config.selectWeapon !== false && (player.weaponIndex !== weapon || player.buildIndex > -1)) {
                            selectWeapon(weapon);
                        }
                        const firstReload = player.reloads && Number(player.reloads[weapon]) || 0;
                        state.checkTick = game.tick;
                        state.afterReload = firstReload;
                        state.fired = firstReload > 0;

                        if (firstReload > 0 || config.retryOnMiss === false) {
                            sendStop(state);
                            clearWait();
                            return;
                        }

                        state.retried = true;
                        state.retryToggleOffTick = game.tick;
                        sendStop(state);

                        game.tickBase(() => {
                            if (config.selectWeapon !== false && (player.weaponIndex !== weapon || player.buildIndex > -1)) {
                                selectWeapon(weapon);
                            }
                            state.retryTick = game.tick;
                            sendStart(state);

                            if (config.sendSecond || _things.SendSecond) {
                                game.tickBase(() => {
                                    if (config.selectWeapon !== false && (player.weaponIndex !== weapon || player.buildIndex > -1)) {
                                        selectWeapon(weapon);
                                    }
                                    const retryReload = player.reloads && Number(player.reloads[weapon]) || 0;
                                    state.retryCheckTick = game.tick;
                                    state.retryReload = retryReload;
                                    state.retryFired = retryReload > 0;
                                    sendStop(state);
                                    clearWait();
                                }, checkTicks);
                            } else {
                                clearWait();
                            }
                        }, 1);
                    }, checkTicks);

                    return true;
                }
