                // Persisted hitbox profiler (server-confirmed melee hits only).
                const HITBOX_PROFILE_LS_KEY = "wingets.hitboxProfiler.v1";
                const HITBOX_ANGLE_BIN_DEG = 5;
                const HITBOX_NEED_BIN = 4;
                const HITBOX_NEED_MAX = 220;
                const HITBOX_SAVE_DEBOUNCE_MS = 1250;
                const HITBOX_MAX_HALF_DEG = 90;
                let hitboxProfileStore;
                let hitboxProfileDirty = false;
