                function _ensureHitboxWeaponProfile(wid) {
                    const key = String(wid);
                    const store = hitboxProfileStore.weapons;
                    let entry = store[key];
                    if (!entry || !Array.isArray(entry.angleBins) || !Array.isArray(entry.needBins)) {
                        entry = _newHitboxWeaponProfile();
                        store[key] = entry;
                    }
                    return entry;
                }
                function _normalizeAngleDiffSigned(a, b) {
                    let d = a - b;
                    while (d > Math.PI) d -= Math.PI * 2;
                    while (d < -Math.PI) d += Math.PI * 2;
                    return d;
                }
                function _recordMeleeHitboxSamples(attacker, wid, hitObjects) {
                    try {
                        if (!attacker || !player || attacker.sid !== player.sid) return;
                        if (!Array.isArray(hitObjects) || !hitObjects.length) return;
                        const weaponId = Number(wid);
                        if (!Number.isFinite(weaponId)) return;
                        const wx = Number.isFinite(attacker.x2) ? attacker.x2 : attacker.x;
                        const wy = Number.isFinite(attacker.y2) ? attacker.y2 : attacker.y;
                        if (!Number.isFinite(wx) || !Number.isFinite(wy)) return;
                        const wdir = Number.isFinite(attacker.dir) ? attacker.dir : 0;
                        const profile = _ensureHitboxWeaponProfile(weaponId);
                        let added = 0;

                        for (let i = 0; i < hitObjects.length; i++) {
                            const obj = hitObjects[i];
                            if (!obj) continue;
                            const ox = Number.isFinite(obj.x) ? obj.x : obj.x2;
                            const oy = Number.isFinite(obj.y) ? obj.y : obj.y2;
                            if (!Number.isFinite(ox) || !Number.isFinite(oy)) continue;
                            const objScale = typeof obj.getScale === "function" ? obj.getScale() : (obj.scale || 0);
                            const dist = typeof getDistance === "function" ? getDistance(wx, wy, ox, oy) : Math.hypot(ox - wx, oy - wy);
                            const neededDist = Math.max(0, dist - (Number(objScale) || 0));
                            const toObj = Math.atan2(oy - wy, ox - wx);
                            const absDeg = Math.abs(_normalizeAngleDiffSigned(toObj, wdir)) * 180 / Math.PI;

                            const angleBin = Math.max(0, Math.min(profile.angleBins.length - 1, Math.floor(absDeg / HITBOX_ANGLE_BIN_DEG)));
                            const needBin = Math.max(0, Math.min(profile.needBins.length - 1, Math.floor(Math.min(HITBOX_NEED_MAX, neededDist) / HITBOX_NEED_BIN)));

                            profile.angleBins[angleBin] = (profile.angleBins[angleBin] || 0) + 1;
                            profile.needBins[needBin] = (profile.needBins[needBin] || 0) + 1;
                            profile.samples++;
                            if (absDeg > profile.maxAbsAngleDeg) profile.maxAbsAngleDeg = absDeg;
                            if (neededDist > profile.maxNeededDist) profile.maxNeededDist = neededDist;
                            profile.lastSampleAt = Date.now();
                            added++;
                        }

                        if (added > 0) {
                            hitboxProfileStore.totalSamples = (hitboxProfileStore.totalSamples || 0) + added;
                            _scheduleHitboxProfileSave();
                        }
                    } catch { }
                }
                function _quantileFromBins(bins, step, q = 0.95) {
                    if (!Array.isArray(bins) || !bins.length) return null;
                    let total = 0;
                    for (let i = 0; i < bins.length; i++) total += bins[i] || 0;
                    if (!total) return null;
                    const target = Math.max(1, Math.ceil(total * Math.max(0, Math.min(1, q))));
                    let acc = 0;
                    for (let i = 0; i < bins.length; i++) {
                        acc += bins[i] || 0;
                        if (acc >= target) return (i + 0.5) * step;
                    }
                    return (bins.length - 0.5) * step;
                }
