                    const effectiveRange = Math.max(0, (Number(weapon.range) || 0) - (Number(weapon.xeOff) || 0));
                    const qAngle = _quantileFromBins(profile.angleBins, HITBOX_ANGLE_BIN_DEG, q);
                    const qNeed = _quantileFromBins(profile.needBins, HITBOX_NEED_BIN, q);
                    const paddedAngle = qAngle == null ? null : Math.min(HITBOX_MAX_HALF_DEG, qAngle + 1.5);
                    const paddedNeed = qNeed == null ? null : (qNeed + 1);
