                            const hasTarget = Number.isInteger(targetSid) && targetSid > 0;
                            const hasAttacker = Number.isInteger(providedAttacker) && providedAttacker > 0;

                            // explicit disable
                            if (!rawId || rawId === "." || rawId.toLowerCase() === "off") {
                                clearKillTargeting();
                                return;
                            }

                            // do not wipe current target on invalid input (e.g. "!k sid")
                            if (!hasTarget) {
                                sendChat(`Usage: ${_prefix}k <sid> [controllerSid] or ${_prefix}k off`);
                                return;
                            }

                            GM_setValue('k', targetSid);
                            sendUpdate('k', targetSid, 0);

                            const attackerSid = hasAttacker ? providedAttacker : null;
                            GM_setValue('kk', attackerSid);
                            sendUpdate('kk', attackerSid, 0);

                            // turn on kill-mode immediately so we don't fall back to breaker/closest
                            GM_setValue('breaker', false);
                            sendUpdate('breaker', false, 0);
