                                    const spikeR = (typeof FindSpike.getScale === "function" ? FindSpike.getScale() : FindSpike.scale) || 0;

                                    const angToEnemy = Math.atan2(ey - py, ex - px);
                                    const angToSpike = Math.atan2(sy - py, sx - px);
                                    const signedDiff = Math.atan2(Math.sin(angToEnemy - angToSpike), Math.cos(angToEnemy - angToSpike));
                                    const absDiff = Math.abs(signedDiff);
                                    const deg = absDiff * 180 / Math.PI;
                                    let bucket = deg <= 30 ? "aligned" : deg >= 135 ? "opposite" : "side";

                                    const desiredR = 70;
                                    const angEP = Math.atan2(py - ey, px - ex);
                                    const angES = Math.atan2(sy - ey, sx - ex);
                                    const angBehind = Math.atan2(Math.sin(angES + Math.PI), Math.cos(angES + Math.PI));
                                    const delta = Math.atan2(Math.sin(angBehind - angEP), Math.cos(angBehind - angEP));
                                    const absDelta = Math.abs(delta);
                                    const turnSign = Math.sign(delta) || 1;
                                    const distEP = Math.hypot(px - ex, py - ey) || 1;

