                                    const esDirY = esY / esLen;
                                    const proj = ((px - ex) * esDirX) + ((py - ey) * esDirY);
                                    const lateral = Math.abs(((px - ex) * esDirY) - ((py - ey) * esDirX));
                                    const laneHalfWidth = playerR + enemyR * 0.35;
                                    const isBetweenSpikeEnemy = proj > 0 && proj < (esLen + spikeR) && lateral <= laneHalfWidth;

