                                        const quarter = Math.min(absDelta, Math.PI / 2);
                                        stepAngle = angEP + turnSign * quarter;
                                        targetX = ex + desiredR * Math.cos(stepAngle);
                                        targetY = ey + desiredR * Math.sin(stepAngle);
