                // RENDER LEAF:
                function renderLeaf(x, y, l, r, ctxt) {
                    let endX = x + (l * Math.cos(r));
                    let endY = y + (l * Math.sin(r));
                    let width = l * 0.4;
                    ctxt.moveTo(x, y);
                    ctxt.beginPath();
                    ctxt.quadraticCurveTo(((x + endX) / 2) + (width * Math.cos(r + Math.PI / 2)),
                        ((y + endY) / 2) + (width * Math.sin(r + Math.PI / 2)), endX, endY);
                    ctxt.quadraticCurveTo(((x + endX) / 2) - (width * Math.cos(r + Math.PI / 2)),
                        ((y + endY) / 2) - (width * Math.sin(r + Math.PI / 2)), x, y);
                    ctxt.closePath();
                    ctxt.fill();
                    ctxt.stroke();
                }

                // RENDER CIRCLE:
                function renderCircle(x, y, scale, tmpContext, dontStroke, dontFill, strokeCol) {
                    tmpContext = tmpContext || mainContext;
                    tmpContext.beginPath();
                    let oldCT = tmpContext.strokeStyle
                    if (strokeCol) tmpContext.strokeStyle = strokeCol;
                    tmpContext.arc(x, y, scale, 0, 2 * Math.PI);
                    if (!dontFill) tmpContext.fill();
                    if (!dontStroke) tmpContext.stroke();
                    tmpContext.strokeStyle = oldCT;
                }

                function renderHealthCircle(x, y, scale, tmpContext, dontStroke, dontFill) {
                    tmpContext = tmpContext || mainContext;
                    tmpContext.beginPath();
                    tmpContext.arc(x, y, scale, 0, 2 * Math.PI);
                    if (!dontFill) tmpContext.fill();
                    if (!dontStroke) tmpContext.stroke();
                }

                // RENDER STAR SHAPE:
                function renderStar(ctxt, spikes, outer, inner) {
                    let rot = Math.PI / 2 * 3;
                    let x, y;
                    let step = Math.PI / spikes;
                    ctxt.beginPath();
                    ctxt.moveTo(0, -outer);
                    for (let i = 0; i < spikes; i++) {
                        x = Math.cos(rot) * outer;
                        y = Math.sin(rot) * outer;
                        ctxt.lineTo(x, y);
                        rot += step;
                        x = Math.cos(rot) * inner;
                        y = Math.sin(rot) * inner;
                        ctxt.lineTo(x, y);
                        rot += step;
                    }
                    ctxt.lineTo(0, -outer);
                    ctxt.closePath();
                }

                function renderHealthStar(ctxt, spikes, outer, inner) {
                    let rot = Math.PI / 2 * 3;
                    let x, y;
                    let step = Math.PI / spikes;
                    ctxt.beginPath();
                    ctxt.moveTo(0, -outer);
                    for (let i = 0; i < spikes; i++) {
                        x = Math.cos(rot) * outer;
                        y = Math.sin(rot) * outer;
                        ctxt.lineTo(x, y);
                        rot += step;
                        x = Math.cos(rot) * inner;
                        y = Math.sin(rot) * inner;
                        ctxt.lineTo(x, y);
                        rot += step;
                    }
                    ctxt.lineTo(0, -outer);
                    ctxt.closePath();
                }

                // RENDER RECTANGLE:
                function renderRect(x, y, w, h, ctxt, dontStroke, dontFill) {
                    if (!dontFill) ctxt.fillRect(x - (w / 2), y - (h / 2), w, h);
                    if (!dontStroke) ctxt.strokeRect(x - (w / 2), y - (h / 2), w, h);
                }

                function renderHealthRect(x, y, w, h, ctxt, dontStroke, dontFill) {
                    if (!dontFill) ctxt.fillRect(x - (w / 2), y - (h / 2), w, h);
                    if (!dontStroke) ctxt.strokeRect(x - (w / 2), y - (h / 2), w, h);
                }

                // RENDER RECTCIRCLE:
                function renderRectCircle(x, y, s, sw, seg, ctxt, dontStroke, dontFill) {
                    ctxt.save();
                    ctxt.translate(x, y);
                    seg = Math.ceil(seg / 2);
                    for (let i = 0; i < seg; i++) {
                        renderRect(0, 0, s * 2, sw, ctxt, dontStroke, dontFill);
                        ctxt.rotate(Math.PI / seg);
                    }
                    ctxt.restore();
                }

                // RENDER BLOB:
                function renderBlob(ctxt, spikes, outer, inner) {
                    let rot = Math.PI / 2 * 3;
                    let x, y;
                    let step = Math.PI / spikes;
                    let tmpOuter;
                    ctxt.beginPath();
                    ctxt.moveTo(0, -inner);
                    for (let i = 0; i < spikes; i++) {
                        tmpOuter = UTILS.randInt(outer + 0.9, outer * 1.2);
                        ctxt.quadraticCurveTo(Math.cos(rot + step) * tmpOuter, Math.sin(rot + step) * tmpOuter,
                            Math.cos(rot + (step * 2)) * inner, Math.sin(rot + (step * 2)) * inner);
                        rot += step * 2;
                    }
                    ctxt.lineTo(0, -inner);
                    ctxt.closePath();
                }

                // RENDER TRIANGLE:
                function renderTriangle(s, ctx) {
                    ctx = ctx || mainContext;
                    let h = s * (Math.sqrt(3) / 2);
                    ctx.beginPath();
                    ctx.moveTo(0, -h / 2);
                    ctx.lineTo(-s / 2, h / 2);
                    ctx.lineTo(s / 2, h / 2);
                    ctx.lineTo(0, -h / 2);
                    ctx.fill();
                    ctx.closePath();
                }
                function getWeaponMetaSafe(obj, items) {
                    const w = (obj && Number.isInteger(obj.weaponIndex) && items?.weapons?.[obj.weaponIndex])
                        ? items.weapons[obj.weaponIndex]
                        : null;

                    return {
                        has: !!w,
                        aboveHand: !!w?.aboveHand,
                        projectileId: (w && 'projectile' in w) ? w.projectile : null,
                        hideProjectile: !!w?.hideProjectile,
                        armS: Number.isFinite(w?.armS) ? w.armS : 1,
                        hndS: Number.isFinite(w?.hndS) ? w.hndS : 1,
                        hndD: Number.isFinite(w?.hndD) ? w.hndD : 1,
                        toolWeapon: w
                    };
                }

                // PREPARE MENU BACKGROUND:
                function prepareMenuBackground() {
                    var tmpMid = config.mapScale / 2;
                    objectManager.add(0, tmpMid, tmpMid + 200, 0, config.treeScales[3], 0);
                    objectManager.add(1, tmpMid, tmpMid - 480, 0, config.treeScales[3], 0);
                    objectManager.add(2, tmpMid + 300, tmpMid + 450, 0, config.treeScales[3], 0);
                    objectManager.add(3, tmpMid - 950, tmpMid - 130, 0, config.treeScales[2], 0);
                    objectManager.add(4, tmpMid - 750, tmpMid - 400, 0, config.treeScales[3], 0);
                    objectManager.add(5, tmpMid - 700, tmpMid + 400, 0, config.treeScales[2], 0);
                    objectManager.add(6, tmpMid + 800, tmpMid - 200, 0, config.treeScales[3], 0);
                    objectManager.add(7, tmpMid - 260, tmpMid + 340, 0, config.bushScales[3], 1);
                    objectManager.add(8, tmpMid + 760, tmpMid + 310, 0, config.bushScales[3], 1);
                    objectManager.add(9, tmpMid - 800, tmpMid + 100, 0, config.bushScales[3], 1);
                    objectManager.add(10, tmpMid - 800, tmpMid + 300, 0, items.list[4].scale, items.list[4].id, items.list[10]);
                    objectManager.add(11, tmpMid + 650, tmpMid - 390, 0, items.list[4].scale, items.list[4].id, items.list[10]);
                    objectManager.add(12, tmpMid - 400, tmpMid - 450, 0, config.rockScales[2], 2);
                }
                const speed = 35;
                function renderBiomeOutlines(xOffset, yOffset, ctx, style = {}) {
                    const S = (style.biomeOutlines || {});
                    if (S.enabled === false) return;

                    const lineW = S.width ?? 2;
                    const alpha = S.alpha ?? 0.15;
                    const colSG = (S.colors && S.colors.snowGrass) || S.color || "#FFFFFF";
                    const colGD = (S.colors && S.colors.grassDesert) || S.color || "#FFFFFF";
                    const dash = S.dash || [8, 6];

                    // screen-space Y positions for the two biome seams:
                    // - snow/grass seam: config.snowBiomeTop
                    // - grass/desert seam: config.mapScale - config.snowBiomeTop
                    const ySG = Math.round(config.snowBiomeTop - yOffset) + 0.5;                         // snow/grass
                    const yGD = Math.round((config.mapScale - config.snowBiomeTop) - yOffset) + 0.5;     // grass/desert

                    ctx.save();
                    ctx.lineWidth = lineW;
                    ctx.setLineDash(dash);
                    ctx.globalAlpha = alpha;

                    // Optional shadow for contrast on dark maps
                    if (S.shadowBlur) {
                        ctx.shadowBlur = S.shadowBlur;
                        ctx.shadowColor = S.shadowColor || "rgba(0,0,0,0.7)";
                    }

                    // draw a line only if itâ€™s on screen
                    const drawHLine = (y, color) => {
                        if (y >= 0 && y <= maxScreenHeight) {
                            ctx.beginPath();
                            ctx.strokeStyle = color;
                            ctx.moveTo(0, y);
                            ctx.lineTo(maxScreenWidth, y);
                            ctx.stroke();
                        }
                    };

                    drawHLine(ySG, colSG);
                    drawHLine(yGD, colGD);

                    ctx.restore();
                }

                function renderDeadPlayers(xOffset, yOffset, opts = {}) {
                    const compute = opts.compute !== false;
                    const draw = opts.draw !== false;
                    if (draw) {
                        mainContext.fillStyle = "#91b2db";
                    }
                    const currentTime = Date.now();
                    for (let i = 0; i < deadPlayers.length; ++i) {
                        const dead = deadPlayers[i];
                        if (!dead || !dead.active) continue;
                        if (compute) {
                            if (!dead.startTime) {
                                dead.startTime = currentTime;
                                dead.angle = 0;
                                dead.radius = 0.1;
                                dead.fallSpeed = 0.5;
                            }
                            const timeElapsed = currentTime - dead.startTime;
                            const maxAlpha = 1;
                            dead.alpha = Math.max(0, maxAlpha - (timeElapsed / 3000));
                            dead.animate(delta);
                            dead.fallSpeed += 0.05;
                            dead.y += dead.fallSpeed;
                            dead.angle += 0.05;
                            if (timeElapsed >= 3000) {
                                dead.active = false;
                                dead.startTime = null;
                            }
                        }
                        if (draw && dead.active) {
                            mainContext.globalAlpha = dead.alpha ?? 1;
                            mainContext.strokeStyle = outlineColor;
                            mainContext.save();
                            mainContext.translate(dead.x - xOffset, dead.y - yOffset);
                            mainContext.rotate(dead.angle || 0);
                            renderDeadPlayer(dead, mainContext);
                            mainContext.restore();
                            mainContext.fillStyle = "#91b2db";
                        }
                    }
                }

                // RENDER PLAYERS:
                damageIndicatorFontSize = 30; // px â€” change this in the console


                // â”€â”€â”€â”€â”€â”€â”€â”€â”€ Helper draw functions (same as before) â”€â”€â”€â”€â”€â”€â”€â”€â”€
                const drawEnemyLowHealth = (ctx, e, xOffset, yOffset) => {
                    const lowHealthThreshold = 30;
                    if (!(e && e.health != null && e.maxHealth != null) || e.health > lowHealthThreshold) return;
                    const radius = (e.getScale ? e.getScale() : e.scale) || 30;
                    const x = e.x - xOffset, y = e.y - yOffset;
                    ctx.save();
                    ctx.strokeStyle = "rgba(255, 0, 0, 0.8)";
                    ctx.lineWidth = 3;
                    ctx.beginPath(); ctx.arc(x, y, radius + 10, 0, Math.PI * 2); ctx.stroke();
                    ctx.restore();
                };

                let instaRingTime = 0;
                const drawDamageIndicator = (ctx, e, xOffset, yOffset) => {
                    const dmg = e?.damageThreat;
                    if (!(dmg > 0)) return;
                    const radius = e.scale || 20;
                    const x = e.x - xOffset, y = e.y - yOffset - (radius + 10);
                    const maxDmg = 100;
                    const clamped = Math.min(dmg, maxDmg);
                    const ratio = clamped / maxDmg;
                    const r = Math.floor(ratio * 255);
                    const g = Math.floor((1 - ratio) * 255);
                    const text = dmg >= 101 ? "INSTA" : `â€“${Math.round(dmg)}`;
                    ctx.save();
                    ctx.globalAlpha = 1;
                    ctx.fillStyle = `rgba(${r}, ${g}, 0, 0.9)`;
                    ctx.font = `bold ${window.damageIndicatorFontSize || 16}px Arial`;
                    ctx.textAlign = "center";
                    ctx.fillText(text, x, y);
                    ctx.restore();
                    ctx.globalAlpha = playerglobalAlpha;
                };



                const drawInstaZone = (ctx, e, xOffset, yOffset) => {
                    if (!e || !(e.damageThreat >= 101)) return;
                    const x = e.x - xOffset, y = e.y - yOffset;

                    // weapon range if available; else 0
                    const wId0 = Array.isArray(e.weapons) ? e.weapons[0] : null;
                    const w0 = (Number.isInteger(wId0) && items?.weapons?.[wId0]) ? items.weapons[wId0] : null;
                    const wRange = w0?.range || 0;

                    const baseRadius = (e.scale || 20) + 10;
                    const pulse = Math.sin(instaRingTime * 4) * 4;
                    const radius = baseRadius + pulse + wRange;
                    const glowAlpha = 0.4 + (Math.sin(instaRingTime * 4) + 1) * 0.3;

                    ctx.save();
                    ctx.beginPath();
                    ctx.arc(x, y, radius, 0, Math.PI * 2);
                    ctx.strokeStyle = `rgba(255, 0, 0, ${glowAlpha.toFixed(2)})`;
                    ctx.lineWidth = 4 + pulse * 0.2;
                    ctx.shadowColor = `rgba(255, 0, 0, ${glowAlpha.toFixed(2)})`;
                    ctx.shadowBlur = 20 + pulse * 1.5;
                    ctx.stroke();
                    ctx.restore();
                };

                function isEnemyPlayer(targetPlayer) {
                    if (!targetPlayer || !player) return false;
                    if (!player.team) return true
                    // Check for same SID or same encoded team
                    const sameSID = targetPlayer.sid === player.sid;
                    const sameTeam = targetPlayer.team === player.team;

                    return !(sameSID || sameTeam);
                }

                // â”€â”€â”€â”€â”€â”€â”€â”€â”€ Inject into renderPlayers for all â€œenemiesâ€ â”€â”€â”€â”€â”€â”€â”€â”€â”€
                playerglobalAlpha = .5
                let renderedPlayer = {}
                for (let i = 0; i < 40; i++) {
                    GM_setValue(i, null)
                }
                function renderPlayers(xOffset, yOffset, zIndex, opts = {}) {
                    const compute = opts.compute !== false;
                    const draw = opts.draw !== false;
                    if (draw) {
                        mainContext.globalAlpha = playerglobalAlpha;
                        mainContext.fillStyle = "#91b2db";
                    }
                    for (let i = 0; i < players.length; i++) {
                        const tmpObj = players[i];
                        if (tmpObj.zIndex !== zIndex) continue;

                        if (compute) {
                            tmpObj.animate(delta);
                            if (tmpObj.visible) {
                                tmpObj.skinRot += 0.002 * delta;
                            }
                        }
                        if (!draw || !tmpObj.visible) continue;

                        const tmpDir = (!configs.showDir && !useWasd && tmpObj === player)
                            ? (configs.attackDir ? getVisualDir() : getSafeDir())
                            : (tmpObj.dir || 0);

                        mainContext.save();
                        mainContext.translate(tmpObj.x - xOffset, tmpObj.y - yOffset);
                        mainContext.rotate(tmpDir + tmpObj.dirPlus);
                        renderPlayer(tmpObj, mainContext);
                        mainContext.restore();

                        // â”€â”€â”€ Now draw for every other player â”€â”€â”€
                        if (tmpObj !== player && isEnemyPlayer(tmpObj)) {
                            drawEnemyLowHealth(mainContext, tmpObj, xOffset, yOffset);
                            drawDamageIndicator(mainContext, tmpObj, xOffset, yOffset);
                            drawInstaZone(mainContext, tmpObj, xOffset, yOffset);
                        }
                    }
                }
                function renderPlayers2(xOffset, yOffset, zIndex) {
                    mainContext.globalAlpha = playerglobalAlpha;
                    mainContext.fillStyle = "#91b2db";
                    for (var i = 0; i < players.length; ++i) {
                        tmpObj = players[i];
                        if (tmpObj.zIndex == zIndex) {
                            tmpObj.animate(delta);
                            if (tmpObj.visible) {
                                tmpObj.skinRot += (0.002 * delta);
                                tmpDir = (!configs.showDir && !useWasd && tmpObj == player) ? configs.attackDir ? getVisualDir() : getSafeDir() : (tmpObj.dir || 0);
                                mainContext.save();
                                mainContext.translate(tmpObj.x - xOffset, tmpObj.y - yOffset);

                                // RENDER PLAYER:
                                mainContext.rotate(tmpDir + tmpObj.dirPlus);
                                renderPlayer(tmpObj, mainContext);
                                mainContext.restore();

                            }
                        }
                    }
                }

                // RENDER DEAD PLAYER:
                function renderDeadPlayer(obj, ctxt) {
                    ctxt = ctxt || mainContext;
                    ctxt.lineWidth = outlineWidth;
                    ctxt.lineJoin = "miter";
                    let handAngle = (Math.PI / 4) * (items.weapons[obj.weaponIndex].armS || 1);
                    let oHandAngle = (obj.buildIndex < 0) ? (items.weapons[obj.weaponIndex].hndS || 1) : 1;
                    let oHandDist = (obj.buildIndex < 0) ? (items.weapons[obj.weaponIndex].hndD || 1) : 1;

                    // WEAPON BELLOW HANDS:
                    if (obj.buildIndex < 0 && !items.weapons[obj.weaponIndex].aboveHand) {
                        renderTool(items.weapons[obj.weaponIndex], config.weaponVariants[obj.weaponVariant].src, obj.scale, 0, ctxt);
                        if (items.weapons[obj.weaponIndex].projectile != undefined && !items.weapons[obj.weaponIndex].hideProjectile) {
                            renderProjectile(obj.scale, 0,
                                items.projectiles[items.weapons[obj.weaponIndex].projectile], mainContext);
                        }
                    }

                    // HANDS:
                    ctxt.fillStyle = config.skinColors[obj.skinColor];
                    renderCircle(obj.scale * Math.cos(handAngle), (obj.scale * Math.sin(handAngle)), 14);
                    renderCircle((obj.scale * oHandDist) * Math.cos(-handAngle * oHandAngle),
                        (obj.scale * oHandDist) * Math.sin(-handAngle * oHandAngle), 14);

                    // WEAPON ABOVE HANDS:
                    if (obj.buildIndex < 0 && items.weapons[obj.weaponIndex].aboveHand) {
                        renderTool(items.weapons[obj.weaponIndex], config.weaponVariants[obj.weaponVariant].src, obj.scale, 0, ctxt);
                        if (items.weapons[obj.weaponIndex].projectile != undefined && !items.weapons[obj.weaponIndex].hideProjectile) {
                            renderProjectile(obj.scale, 0,
                                items.projectiles[items.weapons[obj.weaponIndex].projectile], mainContext);
                        }
                    }

                    // BUILD ITEM:
                    if (obj.buildIndex >= 0) {
                        var tmpSprite = getItemSprite(items.list[obj.buildIndex]);
                        ctxt.drawImage(tmpSprite, obj.scale - items.list[obj.buildIndex].holdOffset, -tmpSprite.width / 2);
                    }

                    // BODY:
                    renderCircle(0, 0, obj.scale, ctxt);

                    ctxt.lineWidth = 2;
                    ctxt.fillStyle = "#555";
                    ctxt.font = "35px Hammersmith One";
                    ctxt.textBaseline = "middle";
                    ctxt.textAlign = "center";

                    ctxt.fillText("(", 20, 5);

                    ctxt.rotate(Math.PI / 2);
                    ctxt.font = "30px Hammersmith One";
                    ctxt.fillText("E", -15, 15 / 2);
                    ctxt.fillText("Z", 15, 15 / 2);

                }

                // RENDER PLAYER:
                function renderPlayer(obj, ctxt) {
                    ctxt = ctxt || mainContext;
                    ctxt.lineWidth = outlineWidth;
                    ctxt.lineJoin = "miter";
                    let handAngle = (Math.PI / 4) * (items.weapons[obj.weaponIndex].armS || 1);
                    let oHandAngle = (obj.buildIndex < 0) ? (items.weapons[obj.weaponIndex].hndS || 1) : 1;
                    let oHandDist = (obj.buildIndex < 0) ? (items.weapons[obj.weaponIndex].hndD || 1) : 1;

                    let katanaMusket = (obj == player && obj.weapons[0] == 3 && obj.weapons[1] == 15);

                    // TAIL/CAPE:
                    if (obj.tailIndex > 0) {
                        renderTail(obj.tailIndex, ctxt, obj);
                    }

                    // WEAPON BELLOW HANDS:
                    if (obj.buildIndex < 0 && !items.weapons[obj.weaponIndex].aboveHand) {
                        renderTool(items.weapons[katanaMusket ? 4 : obj.weaponIndex], config.weaponVariants[obj.weaponVariant].src, obj.scale, 0, ctxt);
                        if (items.weapons[obj.weaponIndex].projectile != undefined && !items.weapons[obj.weaponIndex].hideProjectile) {
                            renderProjectile(obj.scale, 0,
                                items.projectiles[items.weapons[obj.weaponIndex].projectile], mainContext);
                        }
                    }

                    // HANDS:
                    let ob = obj.sid == player.sid && (colors[mode]) || {}
                    ctxt.fillStyle = obj.sid == player.sid ? colors[mode] && (colors[mode].base) || config.skinColors[obj.skinColor] : config.skinColors[obj.skinColor];
                    renderCircle(obj.scale * Math.cos(handAngle), (obj.scale * Math.sin(handAngle)), 14);
                    renderCircle((obj.scale * oHandDist) * Math.cos(-handAngle * oHandAngle),
                        (obj.scale * oHandDist) * Math.sin(-handAngle * oHandAngle), 14);

                    // WEAPON ABOVE HANDS:
                    if (obj.buildIndex < 0 && items.weapons[obj.weaponIndex].aboveHand) {
                        renderTool(items.weapons[obj.weaponIndex], config.weaponVariants[obj.weaponVariant].src, obj.scale, 0, ctxt);
                        if (items.weapons[obj.weaponIndex].projectile != undefined && !items.weapons[obj.weaponIndex].hideProjectile) {
                            renderProjectile(obj.scale, 0,
                                items.projectiles[items.weapons[obj.weaponIndex].projectile], mainContext);
                        }
                    }

                    // BUILD ITEM:
                    if (obj.buildIndex >= 0) {
                        var tmpSprite = getItemSprite(items.list[obj.buildIndex]);
                        ctxt.drawImage(tmpSprite, obj.scale - items.list[obj.buildIndex].holdOffset, -tmpSprite.width / 2);
                    }

                    // BODY:
                    // SKIN:
                    let didrender = false;
                    if (ob.goUnder && false)
                        if (obj.skinIndex > 0) {
                            didrender = true
                            ctxt.rotate(Math.PI / 2);
                            renderSkin(obj.skinIndex, ctxt, null, obj);
                        }
                    let oldSS = ctxt.strokeStyle
                    ctxt.strokeStyle = ob.outline
                    renderCircle(0, 0, obj.scale, ctxt);
                    ctxt.strokeStyle = oldSS
                    if (!didrender)
                        if (obj.skinIndex > 0) {
                            didrender = true
                            ctxt.rotate(Math.PI / 2);
                            renderSkin(obj.skinIndex, ctxt, null, obj);
                        }

                }
                // RENDER SKINS:
                let skinSprites = {};
                let skinPointers = {};
                let tmpSkin;
                const faces = {
                    cat1: {
                        src: "https://i.giphy.com/YCTDxuDtkvehXzvhyC.webp",
                        rotateAdd: Math.PI,
                        dif: [0, 15]
                    },
                    cat2: {
                        src: "data:image/png;base64,",
                        rotateAdd: Math.PI,
                        dif: [0, 15]
                    },
                    fox1: {
                        src: "data:image/png;base64,",
                        rotateAdd: Math.PI,
                        dif: [0, 0]
                    },
                    wolf1: {
                        src: "data:image/png;base64,",
                        rotateAdd: Math.PI,
                        dif: [0, 35]
                    },
                    bunny1: {
                        dif: [0, 60],
                        scale: 1.8,
                        rotateAdd: Math.PI,
                        src: "data:image/png;base64,"
                    },
                    slinker: {
                        src: "data:image/png;base64,",
                        rotateAdd: Math.PI,
                        dif: [0, 35]
                    }
                }
                const tails = {
                    cat1: {
                        src: "data:image/png;base64,",
                        get rotateAdd() {
                            return Math.PI / 2
                        },
                        dif: [-10, 10]
                    },
                    fox1: {
                        src: "data:image/png;base64,",
                        rotateAdd: -1.5707963267948966,
                        dif: [-10, 6]
                    },
                    wolf1: {
                        src: "data:image/png;base64,",
                        rotateAdd: Math.PI,
                        dif: [-10, 17]
                    },
                    bunny: {
                        src: "data:image/png;base64,",
                        rotateAdd: Math.PI,
                        dif: [0, 0]
                    },
                    slinker: {
                        src: "data:image/png;base64,",
                        rotateAdd: Math.PI * 1.2,
                        dif: [-15, 35],
                        scaleW: 1.8,
                        scaleH: 1.8
                    },
                }
                const colors = {
                    bunny: {
                        base: "#FAEED8"
                    },
                    slinker: {
                        goUnder: true,
                        base: '#E79B4C', // warm tan fur
                        outline: '#111945'  // deep navy line
                    }
                }
                custom = {
                    cat: {
                        0: {
                            50: faces.cat1,
                            22: faces.cat1,
                            12: faces.cat1,
                            6: faces.cat2,
                        },
                        1: {
                            11: tails.cat1
                        }
                    },
                    fox: {
                        0: {
                            50: faces.fox1,
                            22: faces.fox1,
                            12: faces.fox1,
                            6: faces.fox1,
                        },
                        1: {
                            11: tails.fox1
                        }
                    },
                    wolf: {
                        0: {
                            50: faces.wolf1,
                            22: faces.wolf1,
                            12: faces.wolf1,
                            6: faces.wolf1,
                        },
                        1: {
                            11: tails.wolf1
                        }
                    },
                    bunny: {
                        0: {
                            50: faces.bunny1,
                            22: faces.bunny1,
                            12: faces.bunny1,
                            6: faces.bunny1,
                        },
                        1: {
                            11: tails.bunny
                        }
                    },
                    slinker: {
                        0: {
                            50: faces.slinker,
                            22: faces.slinker,
                            12: faces.slinker,
                            6: faces.slinker,
                        },
                        1: {
                            11: tails.slinker
                        }
                    }
                };
                let modes = Object.keys(custom)
                mode = modes[0]
                const tailRotateAdd = {}
                const skinRotateAdd = {}; // store per ID
                let currentMode = mode
                function clearObj(obj) {
                    Object.keys(obj).forEach(k => delete obj[k]);
                }

                function renderSkin(index, ctxt, parentSkin, owner) {
                    let e = index
                    if (currentMode !== mode) {
                        // wipe all skins so weâ€™ll reload fresh ones
                        clearObj(skinSprites);
                        clearObj(skinRotateAdd);
                        clearObj(skinPointers);
                        clearObj(accessSprites);
                        clearObj(accessPointers);

                        currentMode = mode;
                    }
                    tmpSkin = skinSprites[index];
                    if (!tmpSkin) {
                        let tmpImage = new Image();
                        let src = "https://moomoo.io/img/hats/hat_" + index + ".png"
                        tmpImage.onload = function () {
                            this.isLoaded = true;
                            this.onload = null;
                        };
                        console.log(custom[mode], mode)
                        if (custom[mode]) {
                            const customData = custom[mode][0][e];
                            if (customData) {
                                src = customData.src;
                                skinRotateAdd[e] = customData.rotateAdd || 0;
                            } else {
                                skinRotateAdd[e] = 0;
                            }
                        }
                        tmpImage.src = src;
                        skinSprites[index] = tmpImage;
                        tmpSkin = tmpImage;
                    }
                    let tmpObj = parentSkin || skinPointers[index];
                    if (!tmpObj) {
                        for (let i = 0; i < hats.length; ++i) {
                            if (hats[i].id == index) {
                                tmpObj = hats[i];
                                break;
                            }
                        }
                        skinPointers[index] = tmpObj;
                    }

                    if (tmpSkin.isLoaded) {
                        const rotateOffset = skinRotateAdd[e] || 0;
                        //console.log(index,rotateOffset)
                        if (custom[mode][0][e] && custom[mode][0][e].dif) ctxt.translate(...custom[mode][0][e].dif);
                        ctxt.rotate(rotateOffset);
                        ctxt.drawImage(tmpSkin, -tmpObj.scale / 2, -tmpObj.scale / 2, tmpObj.scale, tmpObj.scale)
                    }
                    if (!parentSkin && tmpObj.topSprite) {
                        ctxt.save();
                        ctxt.rotate(owner.skinRot + Math.PI);
                        renderSkin(index + "_top", ctxt, tmpObj, owner);
                        ctxt.restore();
                    }
                }

                // RENDER TAIL:
                let accessSprites = {};
                let accessPointers = {};
                function renderTail(index, ctxt, owner) {
                    // 1) load image (custom or default)
                    let img = accessSprites[index];
                    if (!img) {
                        img = new Image();
                        img.onload = function () {
                            this.isLoaded = true;
                            this.onload = null;
                        };
                        const customData = custom[mode][1][index];
                        if (customData) {
                            img.src = customData.src;
                            tailRotateAdd[index] = customData.rotateAdd || 0;
                        } else {
                            img.src = `https://moomoo.io/img/accessories/access_${index}.png`;
                            tailRotateAdd[index] = 0;
                        }
                        accessSprites[index] = img;
                    }

                    // 2) find the accessory metadata
                    let obj = accessPointers[index];
                    if (!obj) {
                        obj = accessories.find(a => a.id === index);
                        accessPointers[index] = obj;
                    }
                    if (!obj) {
                        console.warn('cant find', index)
                        obj = {}
                    }
                    // 3) draw if loaded
                    if (img.isLoaded) {
                        ctxt.save();
                        // position offset
                        const customData = custom[mode][1][index];
                        const baseX = -(20 + (obj.xOff || 0));      // <- same as original: -20 - xOff
                        const baseY = 0;

                        const dx = customData && customData.dif ? customData.dif[0] : 0;          // if dif exists, use it, else 0
                        const dy = customData && customData.dif ? customData.dif[1] : 0;          // if dif exists, use it, else 0

                        ctxt.translate(baseX + dx, baseY + dy);

                        let total = [(20 - (obj.xOff || 0)) + (custom[mode][1][index] ? custom[mode][1][index].dif[0] : 0), custom[mode][1][index] ? custom[mode][1][index].dif[1] : 0]
                        ctxt.translate(...total);

                        // apply custom static rotation
                        let scaleW = custom[mode][1][index] ? custom[mode][1][index].scaleW || 1 : 1
                        let scaleH = custom[mode][1][index] ? custom[mode][1][index].scaleH || 1 : 1
                        const staticRot = custom[mode][1][index] ? custom[mode][1][index].rotateAdd : 0;
                        if (staticRot) {
                            // debug log if you wanna verify it
                            //console.log("tail staticRot:", staticRot);
                            ctxt.rotate(staticRot);
                        }

                        // apply dynamic spin if defined
                        if (obj.spin) {
                            ctxt.rotate(owner.skinRot);
                        }

                        // finally draw

                        ctxt.drawImage(
                            img,
                            -obj.scale / 2,
                            -obj.scale / 2,
                            obj.scale * scaleW,
                            obj.scale * scaleH
                        );
                        ctxt.restore();
                    }
                }

                function renderTail2(index, ctxt, owner) {
                    tmpSkin = accessSprites[index];
                    if (!tmpSkin) {
                        let tmpImage = new Image();
                        tmpImage.onload = function () {
                            this.isLoaded = true;
                            this.onload = null;
                        };
                        tmpImage.src = "https://moomoo.io/img/accessories/access_" + index + ".png";
                        accessSprites[index] = tmpImage;
                        tmpSkin = tmpImage;
                    }
                    let tmpObj = accessPointers[index];
                    if (!tmpObj) {
                        for (let i = 0; i < accessories.length; ++i) {
                            if (accessories[i].id == index) {
                                tmpObj = accessories[i];
                                break;
                            }
                        }
                        accessPointers[index] = tmpObj;
                    }
                    if (tmpSkin.isLoaded) {
                        ctxt.save();
                        ctxt.translate(-20 - (tmpObj.xOff || 0), 0);
                        if (tmpObj.spin)
                            ctxt.rotate(owner.skinRot);
                        ctxt.drawImage(tmpSkin, -(tmpObj.scale / 2), -(tmpObj.scale / 2), tmpObj.scale, tmpObj.scale);
                        ctxt.restore();
                    }
                }

                // RENDER TOOL:
                let toolSprites = {};
                function renderTool(obj, variant, x, y, ctxt) {
                    let tmpSrc = obj.src + (variant || "");
                    let tmpSprite = toolSprites[tmpSrc];
                    if (!tmpSprite) {
                        tmpSprite = new Image();
                        tmpSprite.onload = function () {
                            this.isLoaded = true;
                        }
                        tmpSprite.src = "https://moomoo.io/img/weapons/" + tmpSrc + ".png";
                        toolSprites[tmpSrc] = tmpSprite;
                    }
                    if (tmpSprite.isLoaded)
                        ctxt.drawImage(tmpSprite, x + obj.xOff - (obj.length / 2), y + obj.yOff - (obj.width / 2), obj.length, obj.width);
                }

                // RENDER PROJECTILES:
                function renderProjectiles(layer, xOffset, yOffset, opts = {}) {
                    const compute = opts.compute !== false;
                    const draw = opts.draw !== false;
                    for (let i = 0; i < projectiles.length; i++) {
                        tmpObj = projectiles[i];
                        if (tmpObj.active && tmpObj.layer == layer) {
                            if (compute) {
                                tmpObj.update(delta);
                            }
                            if (draw && tmpObj.active && tmpObj.inWindow && isOnScreen(tmpObj.x - xOffset, tmpObj.y - yOffset, tmpObj.scale)) {
                                mainContext.save();
                                mainContext.translate(tmpObj.x - xOffset, tmpObj.y - yOffset);
                                mainContext.rotate(tmpObj.dir);
                                renderProjectile(0, 0, tmpObj, mainContext, 1);
                                mainContext.restore();
                            }
                        }
                    };
                }

                // RENDER PROJECTILE:
                let projectileSprites = {};
                function renderProjectile(x, y, obj, ctxt, debug) {
                    if (obj.src) {
                        let tmpSrc = items.projectiles[obj.indx].src;
                        let tmpSprite = projectileSprites[tmpSrc];
                        if (!tmpSprite) {
                            tmpSprite = new Image();
                            tmpSprite.onload = function () {
                                this.isLoaded = true;
                            }
                            tmpSprite.src = "https://moomoo.io/img/weapons/" + tmpSrc + ".png";
                            projectileSprites[tmpSrc] = tmpSprite;
                        }
                        if (tmpSprite.isLoaded)
                            ctxt.drawImage(tmpSprite, x - (obj.scale / 2), y - (obj.scale / 2), obj.scale, obj.scale);
                    } else if (obj.indx == 1) {
                        ctxt.fillStyle = "#939393";
                        renderCircle(x, y, obj.scale, ctxt);
                    }
                }

                // RENDER AI:
                let aiSprites = {};
                /* per-species ellipse multipliers (rx = horizontal, ry = vertical)  */

                const OVAL_HITBOX = {
                    cow_1: { rx: 1.25, ry: 1.00 },
                    pig_1: { rx: 1.20, ry: 1.00 },
                    bull_2: { rx: 1.10, ry: 0.80 },
                    bull_1: { rx: 1.10, ry: 0.90 },
                    wolf_1: { rx: 1.00, ry: 0.60 },
                    wolf_2: { rx: 1.30, ry: 0.90 },
                    enemy: { rx: 1.50, ry: 1.10 },
                    crate_1: { rx: 1.00, ry: 1.00 },
                    chicken_1: { rx: 1.00, ry: 1.00 },
                    default: { rx: 1.00, ry: 1.00 }
                };

                OVAL_HITBOX.wolf_2.hitBoxRx = 1.8//circle

                function renderAI(obj, ctxt) {
                    let tmpIndx = obj.index;
                    let tmpSprite = aiSprites[tmpIndx];
                    if (!tmpSprite) {
                        let tmpImg = new Image();
                        tmpImg.onload = function () {
                            this.isLoaded = true;
                            this.onload = null;
                        };
                        tmpImg.src = "https://moomoo.io/img/animals/" + obj.src + ".png";
                        tmpSprite = tmpImg;
                        aiSprites[tmpIndx] = tmpSprite;
                    }
                    if (tmpSprite.isLoaded) {
                        let tmpScale = obj.scale * 1.2 * (obj.spriteMlt || 1);
                        ctxt.drawImage(tmpSprite, -tmpScale, -tmpScale, tmpScale * 2, tmpScale * 2);
                    }
                    if (true) {
                        /* collision oval (movement/blocking) */
                        const c = OVAL_HITBOX[obj.src] || OVAL_HITBOX.default;
                        const rx = obj.scale * c.ry;
                        const ry = obj.scale * c.rx;

                        ctxt.save();
                        ctxt.strokeStyle = 'rgba(0,255,0,0.6)'; // green = collision
                        ctxt.lineWidth = 2;
                        ctxt.beginPath();
                        ctxt.ellipse(0, 0, rx, ry, 0, 0, Math.TAU);
                        ctxt.stroke();

                        /* hurt-circle (1.8Ã— scale, independent of oval) */
                        let hurtR = obj.scale * 1.8;
                        ctxt.strokeStyle = 'rgba(255,0,0,0.5)'; // red = hurtbox
                        ctxt.beginPath();
                        ctxt.arc(0, 0, hurtR, 0, Math.TAU);
                        ctxt.stroke();
                        ctxt.restore();

                        hurtR = (obj.scale * 1.8) * .90;
                        ctxt.strokeStyle = 'rgba(255,0,0,0.5)'; // red = hurtbox
                        ctxt.beginPath();
                        ctxt.arc(0, 0, hurtR, 0, Math.TAU);
                        ctxt.stroke();
                        ctxt.restore();
                    }
                }

                // RENDER WATER BODIES:
                function renderWaterBodies(xOffset, yOffset, ctx, padding, style = {}) {
                    // MIDDLE RIVER:
                    const tmpW = (config.riverWidth + (padding | 0));
                    const screenY = (config.mapScale / 2) - yOffset - (tmpW / 2);

                    if (screenY < maxScreenHeight && screenY + tmpW > 0) {
                        // fill (caller should set ctx.fillStyle beforehand)
                        ctx.fillRect(0, screenY, maxScreenWidth, tmpW);

                        // optional outline for readability
                        const WO = (style.water && style.water.outline) || {};
                        if (WO.enabled) {
                            ctx.save();
                            ctx.globalAlpha = WO.alpha ?? 0.35;
                            ctx.lineWidth = WO.width ?? 2;
                            ctx.strokeStyle = WO.color || "#FFFFFF";
                            if (WO.dash) ctx.setLineDash(WO.dash);
                            if (WO.shadowBlur) {
                                ctx.shadowBlur = WO.shadowBlur;
                                ctx.shadowColor = WO.shadowColor || "rgba(0,0,0,0.9)";
                            }

                            // top edge
                            const yTop = Math.round(screenY) + 0.5;
                            if (yTop >= 0 && yTop <= maxScreenHeight) {
                                ctx.beginPath();
                                ctx.moveTo(0, yTop);
                                ctx.lineTo(maxScreenWidth, yTop);
                                ctx.stroke();
                            }
                            // bottom edge
                            const yBot = Math.round(screenY + tmpW) + 0.5;
                            if (yBot >= 0 && yBot <= maxScreenHeight) {
                                ctx.beginPath();
                                ctx.moveTo(0, yBot);
                                ctx.lineTo(maxScreenWidth, yBot);
                                ctx.stroke();
                            }

                            ctx.restore();
                            ctx.setLineDash([]);
                        }
                    }
                }

