                    const nextObj = (idx + 1 < chain.length) ? chain[idx + 1] : finalSpike;
                    const pushDirTrap = nextObj
                        ? UTILS.getDirection(targetObj.x, targetObj.y, nextObj.x, nextObj.y)
                        : UTILS.getDirection(targetObj.x, targetObj.y, near.x, near.y);

