                        //console.warn(`[AP:ARRIVAL] dist=${dist.toFixed(2)} fired! step ${idx}->${_things.autoPushChain.step} chainLen=${chain.length} stand=(${standX.toFixed(1)},${standY.toFixed(1)}) enemy=(${near.x.toFixed(0)},${near.y.toFixed(0)})`);
