                                    const o = gameObjects[i];
                                    if (!o || !o.active || !o.dmg || !o.name || o.name.indexOf("spike") === -1) continue;
                                    const isTeam = (typeof o.isTeamObject === "function") ? o.isTeamObject(player) : false;
                                    if (isTeam) continue;

                                    const rad = (typeof o.getScale === "function") ? o.getScale() : (o.scale || 18);
